t.script:
document.addEventListener('DOMContentLoaded', function() {
    const billingToggle = document.getElementById('billing-toggle');
    const monthlyPrices = document.querySelectorAll('.monthly-price');
    const yearlyPrices = document.querySelectorAll('.yearly-price');
    const subscriptionButtons = document.querySelectorAll('.subscription-button');

    function updatePricing() {
        const isYearly = billingToggle.checked;
        console.log('Updating pricing, isYearly:', isYearly);
        console.log('Monthly prices found:', monthlyPrices.length);
        console.log('Yearly prices found:', yearlyPrices.length);

        monthlyPrices.forEach((price, index) => {
            price.style.display = isYearly ? 'none' : 'block';
            console.log(`Monthly price ${index} display:`, price.style.display);
        });

        yearlyPrices.forEach((price, index) => {
            price.style.display = isYearly ? 'block' : 'none';
            console.log(`Yearly price ${index} display:`, price.style.display);
            console.log(`Yearly price ${index} content:`, price.innerHTML);

            // Check if this price container has data attributes
            const container = price.closest('.pricing-container');
            if (container) {
                console.log(`Container ${index} monthly price:`, container.getAttribute('data-monthly-price'));
                console.log(`Container ${index} yearly price:`, container.getAttribute('data-yearly-price'));
            }
        });

        // Update subscription button URLs
        subscriptionButtons.forEach(button => {
            const planId = button.getAttribute('data-plan-id');
            if (planId) {
                const billingPeriod = isYearly ? 'yearly' : 'monthly';
                const baseUrl = `/subscription/select/${planId}`;
                button.href = `${baseUrl}?billing_period=${billingPeriod}`;
            }
        });
    }

    if (billingToggle) {
        billingToggle.addEventListener('change', updatePricing);
        updatePricing(); // Initialize
    }
});

window.ODOO_BILLING_PERIOD = '';
window.ODOO_ACTUAL_PRICE = ;
window.ODOO_PLAN_ID = ;
console.log('✅ ODOO VARIABLES SET: billing_period =', window.ODOO_BILLING_PERIOD, 'price =', window.ODOO_ACTUAL_PRICE);

xpath.script:
function hideCaptchaPopup() {
    var overlay = document.getElementById('captcha-overlay');
    if (overlay) {
        overlay.style.display = 'none';
        document.body.classList.remove('captcha-locked');
    }
}
document.addEventListener('DOMContentLoaded', function () {
    document.body.classList.add('captcha-locked');
});

function hideCaptchaPopup() {
    var overlay = document.getElementById('captcha-overlay');
    if (overlay) {
        overlay.style.display = 'none';
        document.body.classList.remove('captcha-locked');
    }
}
document.addEventListener('DOMContentLoaded', function () {
    var overlay = document.getElementById('captcha-overlay');
    if (overlay) {
        document.body.classList.add('captcha-locked');
    }
});
